    const closing = gate.close(15_000).then(value => { drained = true; return value })
    await until(async () => JSON.parse(await readFile(path.join(gate.root, 'state.json'), 'utf8')).phase === 'closed')
    const late = []
    await assert.rejects(core.registerProject({ projectKey: 'late-gateway', name: 'Late' })); late.push('Gateway')
    assert.equal((await mcp.callTool({ name: 'forge_register_project', arguments: { projectKey: 'late-mcp', name: 'Late' } })).isError, true); late.push('MCP')
    assert.equal((await fetch(`${httpUrl}/api/projects`, { method: 'POST', headers: { 'x-forge-token': 'synthetic-operational-token', 'content-type': 'application/json' }, body: JSON.stringify({ projectKey: 'late-workbench', name: 'Late' }) })).ok, false); late.push('Workbench')
    await assert.rejects(runEmbeddingWorker({ gateway: core, projectId: project.id, profile: { profileKey: 'late-vector', dimensions: 3 }, provider: { name: 'fixture', model: 'synthetic', embed: async () => { throw new Error('must not call') } } })); late.push('embeddings')
    for (const operation of [() => store.enqueue({ projectId: project.id, taskId: task.id, taskKey: task.taskKey, agentId: agent.id }), () => store.claim({ projectId: project.id, agentId: agent.id, workerId: randomUUID() }), () => store.heartbeat({}), () => store.fenced({}, async () => ({ value: null })), () => store.fail({}), () => store.recoveryCheckpoint(project.id, task.id), () => publisher.publish({ key: 'late', artifact: { title: 'Late', content: 'Late' }, signal: new AbortController().signal })]) await assert.rejects(operation())
    late.push('enqueue', 'claim', 'heartbeat', 'fenced', 'fail', 'recovery', 'report-publication')
    assert.equal(drained, false)
    assert.equal((await stateAdmin.query('SELECT effect_receipt FROM forge_coordinator.jobs WHERE task_id=$1', [task.id])).rows[0].effect_receipt, null)
    releaseEffect.resolve(); assert.equal(await job, 'failed')
    assert.equal(drained, false, 'Embedding external call still admitted')
    releaseEmbed.resolve(); assert.equal((await embeddings).embedded, 1)
    const lease = await closing
    assert.equal((await admin.query("SELECT count(*)::int AS n FROM forge.projects WHERE project_key LIKE 'late-%'")).rows[0].n, 0)
    const saved = (await stateAdmin.query('SELECT * FROM forge_coordinator.jobs WHERE task_id=$1', [task.id])).rows[0]
    assert.ok(saved.effect_receipt); assert.equal(saved.state, 'queued'); assert.equal(handlerCalls, 1); assert.equal(providerCalls, 1)
    await mcp.close(); await mcpServer.close(); mcp = mcpServer = undefined
    await new Promise(resolve => http.close(resolve)); http = undefined
    await core.close(); await store.close()
    // Test direct sessions in both databases, including an existing DDL credential.
